     1|/**
     2| * Investment Timeline Stages — canonical data model for project timelines.
     3| *
     4| * Each deal can have up to 7 standard stages with status tracking.
     5| * Used by InvestmentCard (summary), Deal Detail (full), and landing page.
     6| */
     7|
     8|export type TimelineStageStatus = 'UPCOMING' | 'ACTIVE' | 'DELAYED' | 'COMPLETE';
     9|
    10|export interface TimelineStage {
    11|  id: string;
    12|  name: string;
    13|  startDate: string | null;
    14|  estimatedCompletionDate: string | null;
    15|  actualCompletionDate: string | null;
    16|  status: TimelineStageStatus;
    17|  percentComplete: number;
    18|  note?: string | null;
    19|}
    20|
    21|export interface TimelineSummary {
    22|  estimatedTotalDuration: string;
    23|  currentStage: string;
    24|  completionPercentage: number;
    25|  estimatedCompletionDate: string | null;
    26|  stages: TimelineStage[];
    27|}
    28|
    29|/** The 7 canonical project timeline stages in order. */
    30|export const CANONICAL_TIMELINE_STAGES: readonly string[] = [
    31|  'Acquisition / Closing',
    32|  'Permits / Design',
    33|  'Construction Start',
    34|  'Structural / Rough Work',
    35|  'Interior Finishes',
    36|  'Final Inspection',
    37|  'Sale / Refinance / Distribution',
    38|] as const;
    39|
    40|/**
    41| * Build a timeline summary from deal trust info and raw deal data.
    42| * Falls back to estimated stages based on timeline duration when no
    43| * explicit stages are provided.
    44| */
    45|export function buildTimelineSummary(
    46|  timelineMin: number | undefined,
    47|  timelineMax: number | undefined,
    48|  timelineUnit: 'months' | 'years' | undefined,
    49|  rawStages?: TimelineStage[] | null,
    50|  dealCreatedAt?: string | null,
    51|): TimelineSummary {
    52|  // If explicit stages are provided, use them
    53|  if (rawStages && Array.isArray(rawStages) && rawStages.length > 0) {
    54|    const stages = rawStages;
    55|    const activeStage = stages.find(s => s.status === 'ACTIVE' || s.status === 'DELAYED');
    56|    const completedCount = stages.filter(s => s.status === 'COMPLETE').length;
    57|    const completionPercentage = Math.round((completedCount / stages.length) * 100);
    58|    const min = timelineMin ?? 0;
    59|    const max = timelineMax ?? 0;
    60|    const unit = timelineUnit === 'years' ? 'yr' : 'mo';
    61|    const durationLabel = min > 0 && max > 0
    62|      ? `${min}\u2013${max} ${unit}`
    63|      : max > 0 ? `${max} ${unit}` : min > 0 ? `${min} ${unit}` : 'Pending';
    64|
    65|    const lastEstDate = stages
    66|      .map(s => s.estimatedCompletionDate)
    67|      .filter(Boolean)
    68|      .sort()
    69|      .pop() ?? null;
    70|
    71|    return {
    72|      estimatedTotalDuration: durationLabel,
    73|      currentStage: activeStage?.name ?? (completedCount === stages.length ? 'Completed' : 'Pending'),
    74|      completionPercentage,
    75|      estimatedCompletionDate: lastEstDate,
    76|      stages,
    77|    };
    78|  }
    79|
    80|  // Build estimated stages from timeline duration
    81|  const min = timelineMin ?? 0;
    82|  const max = timelineMax ?? 0;
    83|  const unit = timelineUnit === 'years' ? 'yr' : 'mo';
    84|  const durationLabel = min > 0 && max > 0
    85|    ? `${min}\u2013${max} ${unit}`
    86|    : max > 0 ? `${max} ${unit}` : min > 0 ? `${min} ${unit}` : '';
    87|
    88|  // If no timeline data at all, return empty summary
    89|  if (!durationLabel) {
    90|    return {
    91|      estimatedTotalDuration: 'Timeline pending verification',
    92|      currentStage: 'Pending',
    93|      completionPercentage: 0,
    94|      estimatedCompletionDate: null,
    95|      stages: [],
    96|    };
    97|  }
    98|
    99|  // Generate estimated stages evenly distributed across the timeline
   100|  const totalMonths = (max > 0 ? max : min) * (timelineUnit === 'years' ? 12 : 1);
   101|  const startDate = dealCreatedAt ? new Date(dealCreatedAt) : new Date();
   102|  const monthsPerStage = Math.max(1, Math.floor(totalMonths / CANONICAL_TIMELINE_STAGES.length));
   103|
   104|  const stages: TimelineStage[] = CANONICAL_TIMELINE_STAGES.map((name, idx) => {
   105|    const stageStart = new Date(startDate);
   106|    stageStart.setMonth(stageStart.getMonth() + idx * monthsPerStage);
   107|    const stageEnd = new Date(stageStart);
   108|    stageEnd.setMonth(stageEnd.getMonth() + monthsPerStage);
   109|
   110|    const now = new Date();
   111|    let status: TimelineStageStatus = 'UPCOMING';
   112|    let percentComplete = 0;
   113|
   114|    if (stageEnd < now) {
   115|      status = 'COMPLETE';
   116|      percentComplete = 100;
   117|    } else if (stageStart <= now && stageEnd >= now) {
   118|      const totalDuration = stageEnd.getTime() - stageStart.getTime();
   119|      const elapsed = now.getTime() - stageStart.getTime();
   120|      percentComplete = Math.min(100, Math.max(0, Math.round((elapsed / totalDuration) * 100)));
   121|      status = 'ACTIVE';
   122|    }
   123|
   124|    return {
   125|      id: `stage-${idx + 1}`,
   126|      name,
   127|      startDate: stageStart.toISOString(),
   128|      estimatedCompletionDate: stageEnd.toISOString(),
   129|      actualCompletionDate: status === 'COMPLETE' ? stageEnd.toISOString() : null,
   130|      status,
   131|      percentComplete,
   132|    };
   133|  });
   134|
   135|  const activeStage = stages.find(s => s.status === 'ACTIVE');
   136|  const completedCount = stages.filter(s => s.status === 'COMPLETE').length;
   137|  const completionPercentage = Math.round((completedCount / stages.length) * 100);
   138|  const lastEstDate = stages
   139|    .map(s => s.estimatedCompletionDate)
   140|    .filter(Boolean)
   141|    .sort()
   142|    .pop() ?? null;
   143|
   144|  return {
   145|    estimatedTotalDuration: durationLabel,
   146|    currentStage: activeStage?.name ?? (completedCount === stages.length ? 'Completed' : 'Pending'),
   147|    completionPercentage,
   148|    estimatedCompletionDate: lastEstDate,
   149|    stages,
   150|  };
   151|}
   152|
   153|/** Format a timeline stage status with appropriate color label. */
   154|export function getTimelineStatusColor(status: TimelineStageStatus): string {
   155|  switch (status) {
   156|    case 'COMPLETE': return '#00C48C';
   157|    case 'ACTIVE': return '#FFD700';
   158|    case 'DELAYED': return '#F59E0B';
   159|    case 'UPCOMING': return '#555555';
   160|    default: return '#555555';
   161|  }
   162|}
   163|
   164|/** Format a date string for display (Mon DD, YYYY). */
   165|export function formatTimelineDate(dateStr: string | null): string {
   166|  if (!dateStr) return 'Not available';
   167|  try {
   168|    const date = new Date(dateStr);
   169|    if (isNaN(date.getTime())) return 'Not available';
   170|    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
   171|  } catch {
   172|    return 'Not available';
   173|  }
   174|}

